const fs = require('node:fs');
const path = require('node:path');

// Optional SPA directory, so the patch can be run against a copy of the assembled bundle
// outside the image; the Dockerfile passes none and uses the default.
const spaDir = process.argv[2] ?? '/app/spa';
const version = '11.1.0';
// Bumped with every change to what is patched: the directory name is the import-map URL, so
// a new revision is what stops browsers running a cached chunk from the previous one.
const revision = 'liberia2';
const originalDirName = `openmrs-esm-patient-registration-app-${version}`;
const patchedDirName = `${originalDirName}-${revision}`;
const moduleDir = path.join(spaDir, originalDirName);

const lock = '__liberiaEmrPatientRegistrationSubmission';
const start = 'onSubmit:function(e,n){var t;return(t=function()';
const guardedStart =
  `onSubmit:function(e,n){var t;if(globalThis.${lock})return globalThis.${lock};` +
  `return globalThis.${lock}=(t=function()`;
const finish = '})})()},validationSchema:eV}';
const guardedFinish =
  `})})().finally(function(){globalThis.${lock}=void 0})},validationSchema:eV}`;

// IdentifierInput, compiled. The anchor is the component's whole prologue rather than just
// the insertion point, because the guard reads three minified bindings and each must mean
// what it does here: p = usePatientRegistrationContext(), b = patientIdentifier.autoGeneration,
// x = selectedSource.autoGenerationOption.manualEntryEnabled. Every hook the component calls
// runs before the final return, so returning early keeps React's hook order intact.
const hideMarker = '/*liberiaEmrHideAutoGeneratedIdentifiers*/';
const identifierInputPrologue =
  'let nu=function(e){var n,t=e.patientIdentifier,r=e.fieldName,o=(0,m.useTranslation)().t,' +
  'l=(0,u.useConfig)().defaultPatientIdentifierTypes,s=h().identifierTypes,p=ee(),d=p.isOffline,' +
  'f=p.values,g=p.setFieldValue,y=(0,a.useMemo)(function(){return s.find(function(e){' +
  'return e.uuid===t.identifierTypeUuid})},[t,s]),b=t.autoGeneration,v=t.initialValue,' +
  'A=t.identifierValue,w=t.identifierName,_=t.required,k=t.selectedSource,' +
  'x=null==k||null==(n=k.autoGenerationOption)?void 0:n.manualEntryEnabled,' +
  'C=nc((0,a.useState)(b||v===A),2),z=C[0],E=C[1],M="identifiers.".concat(r,".identifierValue"),' +
  'O=nc((0,$.Mt)(M),2),D=O[0],T=O[1],S=d&&nr(y),I=(0,a.useMemo)(function(){var e={};' +
  'return null==l||l.forEach(function(n){e[n]=!0}),e},[l]),j=(0,a.useCallback)(function(){' +
  'E(!0),g("identifiers.".concat(r),np(ns({},t),{identifierValue:v,selectedSource:k,' +
  'autoGeneration:b}))},[v,E]),N=!_&&z&&(!!v||x),F=!!v&&v!==A||!z&&x;';
const identifierInputRender = 'return i().createElement("div",{className:Q.IDInput}';

const patches = [
  {
    // Registration app 11.1.0 disables its button through Formik state, but two click events
    // can enter onSubmit before React commits that state.
    description: 'duplicate patient registration submission',
    marker: lock,
    replacements: [
      [start, guardedStart],
      [finish, guardedFinish],
    ],
  },
  {
    // An identifier the server generates on submit, and that nobody may type, has no value
    // to show while a patient is being created — only a placeholder. It is not rendered at
    // all then, so it cannot be focused or edited; the Identifiers field still seeds it into
    // the form values, so FormManager still asks IDGen for it when the patient is saved.
    // In edit mode the stored identifiers render exactly as before.
    description: 'auto-generated identifiers while creating a patient',
    marker: hideMarker,
    replacements: [
      [
        identifierInputPrologue + identifierInputRender,
        identifierInputPrologue + `${hideMarker}if(!p.inEditMode&&b&&!x)return null;` + identifierInputRender,
      ],
    ],
  },
];

if (!fs.existsSync(moduleDir)) {
  throw new Error(`Patient registration app ${version} was not assembled at ${moduleDir}`);
}

const sources = new Map();
for (const file of fs.readdirSync(moduleDir).filter((name) => name.endsWith('.js'))) {
  const filePath = path.join(moduleDir, file);
  const source = fs.readFileSync(filePath, 'utf8');
  for (const { marker } of patches) {
    if (source.includes(marker)) {
      throw new Error(`${file} is already patched`);
    }
  }
  sources.set(filePath, source);
}

// Every anchor must occur exactly once across the whole bundle, and all of one patch's anchors
// in the same file — anything else means the compiled input is not the one this was written
// against, and the build must stop rather than guess.
const patchedFiles = new Set();
for (const { description, replacements } of patches) {
  const found = replacements.map(([anchor]) =>
    [...sources].flatMap(([filePath, source]) => {
      const count = source.split(anchor).length - 1;
      return count ? [{ file: path.basename(filePath), filePath, count }] : [];
    }),
  );
  const files = new Set(found.flat().map(({ filePath }) => filePath));
  if (files.size !== 1 || found.some((hits) => hits.length !== 1 || hits[0].count !== 1)) {
    throw new Error(
      `Expected one ${version} implementation for ${description}, found ${JSON.stringify(
        found.map((hits) => hits.map(({ file, count }) => ({ file, count }))),
      )}`,
    );
  }
  const [filePath] = files;
  let source = sources.get(filePath);
  for (const [anchor, replacement] of replacements) {
    source = source.replace(anchor, () => replacement);
  }
  sources.set(filePath, source);
  patchedFiles.add(filePath);
  console.log(`Patched ${description} in ${patchedDirName}/${path.basename(filePath)}`);
}

for (const filePath of patchedFiles) {
  // The published source map describes the unpatched file.
  fs.writeFileSync(filePath, sources.get(filePath).replace(/\/\/# sourceMappingURL=[^\n]+\n?$/, ''));
}

const importMapPath = path.join(spaDir, 'importmap.json');
const importMap = fs.readFileSync(importMapPath, 'utf8');
if (importMap.split(originalDirName).length - 1 !== 1 || importMap.includes(patchedDirName)) {
  throw new Error(`Expected exactly one unpatched ${originalDirName} import-map entry`);
}
fs.writeFileSync(importMapPath, importMap.replace(originalDirName, patchedDirName));
const targetDir = path.join(spaDir, patchedDirName);
try {
  fs.renameSync(moduleDir, targetDir);
} catch (error) {
  if (error && error.code === 'EXDEV') {
    fs.cpSync(moduleDir, targetDir, { recursive: true });
    fs.rmSync(moduleDir, { recursive: true, force: true });
  } else {
    throw error;
  }
}
